def _bridge(cal):
    raw = cal['bridge_raw']
    return np.linalg.lstsq(np.column_stack((np.ones(len(raw)), raw)), cal['true_channel_loads'], rcond=None)[0]

def _loads(block, bridge):
    total = bridge.sum(axis=1)
    return tuple((block[key] @ total[1:] + total[0] for key in ('past_channel_raw', 'hold_channel_raw')))
